effect.shader:
/** RGB → H em [0, 360). Retorna 0 para cinza (não aparece). */
float matiz(vec3 c) {
    float mx = max(c.r, max(c.g, c.b));
    float mn = min(c.r, min(c.g, c.b));
    float delta = mx - mn;
    if (delta < 1e-5) return 0.0;
    float h;
    if (mx == c.r)      h = mod((c.g - c.b) / delta, 6.0);
    else if (mx == c.g) h = (c.b - c.r) / delta + 2.0;
    else                h = (c.r - c.g) / delta + 4.0;
    return h * 60.0;
}

/** RGB → S (do HSV): 0 = cinza, 1 = saturado. */
float saturacao(vec3 c) {
    float mx = max(c.r, max(c.g, c.b));
    float mn = min(c.r, min(c.g, c.b));
    return mx < 1e-5 ? 0.0 : (mx - mn) / mx;
}

/** Luminância ITU-R BT.709 — o cinza perceptual. */
float luma(vec3 c) {
    return dot(c, vec3(0.2126, 0.7152, 0.0722));
}

/** Distância angular na roda de matiz: 170°→190° é 20°, não 340°. */
float distanciaDeMatiz(float a, float b) {
    float d = abs(a - b);
    return min(d, 360.0 - d);
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);

    float hDoPixel = matiz(original.rgb);
    float hAlvo = matiz(targetColor.rgb);
    float d = distanciaDeMatiz(hDoPixel, hAlvo);

    // Pixel dentro da tolerância = 1 (mantém); fora = 0 (dessatura); zona = smoothstep.
    float dentro = 1.0 - smoothstep(tolerance, tolerance + max(softness, 1e-4), d);

    // Pixel pouco saturado (cinza quase) não se "isola" — vira cinza direto.
    float temCor = smoothstep(minSat, minSat + 0.1, saturacao(original.rgb));
    dentro *= temCor;

    vec3 cinza = vec3(luma(original.rgb));
    vec3 pintado = mix(cinza, original.rgb, dentro);

    vec3 cor = mix(original.rgb, pintado, strength);

    fragColor = vec4(cor, original.a);
}
